def rename_map(registry, changes):
    if not isinstance(registry, dict) or not isinstance(changes, list):
        raise ValueError('expected registry dict and changes list')
    if any(not isinstance(k, str) or not k for k in registry):
        raise ValueError('invalid registry key')
    result, targets = {}, set()
    for item in changes:
        if not isinstance(item, dict):
            raise ValueError('invalid change')
        source, target = item.get('source'), item.get('target')
        if not isinstance(source, str) or not source or not isinstance(target, str) or not target:
            raise ValueError('invalid source or target')
        if source not in registry or source in result or target in targets:
            raise ValueError('missing source or duplicate name')
        result[source] = target
        targets.add(target)
    if any(target in registry and target not in result for target in targets):
        raise ValueError('target collides with an unchanged key')
    return result

