from .ranges import parse_range

def serve(data, header=None):
    if not isinstance(data, bytes):
        raise ValueError('expected bytes')
    if header is None:
        return {'status': 200, 'body': data, 'content_range': None}
    start, end = parse_range(header, len(data))
    return {'status': 206, 'body': data[start:end + 1], 'content_range': f'bytes {start}-{end}/{len(data)}'}

