from copy import deepcopy

def normalize(event):
    if not isinstance(event, dict):
        raise ValueError('expected event dict')
    for field in ('id', 'key'):
        if not isinstance(event.get(field), str) or not event[field]:
            raise ValueError('invalid event identity')
    version = event.get('version')
    if type(version) is not int or version < 1 or event.get('action') not in ('put', 'delete'):
        raise ValueError('invalid event version or action')
    action = event['action']
    if (action == 'put') != ('value' in event):
        raise ValueError('invalid event value presence')
    result = {k: event[k] for k in ('id', 'key', 'version', 'action')}
    if action == 'put':
        result['value'] = deepcopy(event['value'])
    return result

