from .validation import normalize

def replay(events):
    if not isinstance(events, list):
        raise ValueError('expected event list')
    values, versions, seen = {}, {}, {}
    for raw in events:
        event = normalize(raw)
        identity, key = event['id'], event['key']
        if identity in seen:
            if seen[identity] != event:
                raise ValueError('conflicting duplicate event')
            continue
        if event['version'] <= versions.get(key, 0):
            raise ValueError('stale event')
        seen[identity] = event
        versions[key] = event['version']
        if event['action'] == 'delete':
            values.pop(key, None)
        else:
            values[key] = event['value']
    return {'values': values, 'versions': versions}

