def split_words(text):
    if not isinstance(text, str):
        raise ValueError('expected string')
    words, chars = [], []
    quote, active, escape = None, False, False
    for char in text:
        if escape:
            chars.append(char)
            escape = False
        elif char == '\\' and quote != "'":
            escape = True
            active = True
        elif quote is not None:
            if char == quote:
                quote = None
            else:
                chars.append(char)
        elif char in "\"'":
            quote = char
            active = True
        elif char in ' \t\r\n':
            if active:
                words.append(''.join(chars))
                chars, active = [], False
        else:
            chars.append(char)
            active = True
    if quote is not None or escape:
        raise ValueError('unterminated quote or escape')
    if active:
        words.append(''.join(chars))
    return words

